import { test, expect } from '@playwright/test';

test.describe('Skip Navigation Links - First Focusable Element', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page-with-skip-nav');
  });

  test('should focus on skip navigation link when page loads', async ({ page }) => {
    // Verify skip navigation link is visible
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    await expect(skipLink).toBeVisible();

    // Verify skip navigation link is the first focusable element
    const firstFocusable = page.locator('[tabindex="0"], [tabindex="-1"], button, [href]');
    await expect(firstFocusable).toHaveCount(1);

    // Verify the skip link is the first focusable element
    const firstFocusableElement = page.locator('[tabindex="0"], [tabindex="-1"], button, [href]');
    await expect(firstFocusableElement).toBeVisible();
    await expect(firstFocusableElement).toHaveCount(1);
    await expect(firstFocusableElement).toContainText('skip to main content');

    // Verify skip link has focus
    await expect(skipLink).toBeFocused();
  });

  test('should move focus to main content when skip navigation link is clicked', async ({ page }) => {
    // Verify skip navigation link is visible and has focus
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    await expect(skipLink).toBeVisible();
    await expect(skipLink).toBeFocused();

    // Click the skip navigation link
    await skipLink.click();

    // Verify focus moves to main content area
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeFocused();

    // Verify main content is visible
    await expect(mainContent).toBeVisible();

    // Verify skip link loses focus
    await expect(skipLink).not.toBeFocused();

    // Verify main content is the first focusable element after click
    const firstFocusable = page.locator('[tabindex="0"], [tabindex="-1"], button, [href]');
    await expect(firstFocusable).toHaveCount(1);
    await expect(firstFocusable).toContainText('main content');
  });
});
